import json,re,html
from html.parser import HTMLParser
from collections import Counter
from pathlib import Path
s=json.loads(Path('source.json').read_text()); a=json.loads(Path('answer.json').read_text()); r=json.loads(Path('reference-targets.json').read_text())
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
class Parse(HTMLParser):
 def __init__(self): super().__init__(convert_charrefs=True);self.parts=[]
 def handle_starttag(self,tag,attrs):
  assert tag in allowed,(tag,attrs)
  assert all(k in ['rowspan','colspan'] and v.isdigit() for k,v in attrs),(tag,attrs)
 def handle_data(self,data): self.parts.append(data)
def plain(x):
 p=Parse();p.feed(x);return ''.join(p.parts)
assert len(a)==len(s)==24
assert len({x['source_id'] for x in a})==24
kinds={'tax_removed','tax_reduced','obligation_removed','obligation_merged','authorization_removed','regime_merged','deadline_reduced','compliance_cost_reduced','tax_increased','obligation_added','deadline_increased','complexity_added','financing_transfer','payment_deferred','relief_extended','relief_preserved','coordination'}
units={'percent','euro','legal_duty','regime','calendar_days','working_days','financing','other'}
for x,y in zip(s,a):
 for k in ['code_id','source_id','source_sha256','number']: assert x[k]==y[k],(k,x['number'])
 for k in ['reason','review_notes','status','proposed_xml','substantive_impact']: assert k in y
 if x.get('benefit_check_required'): assert len(y.get('benefit_review',''))>=100
 z=y['substantive_impact']; assert z['version']==1
 for k in ['assessment','scope_limitations','new_burdens_review']: assert len(z[k])>=40,(x['number'],k)
 if y['status']=='retained_unchanged':
  assert y['proposed_xml'] is None and y['classification']=='retained_necessary' and z['classification']=='retained_necessary' and z['effects']==[]
 else:
  assert y['status']=='rewrite_draft'; prop=plain(y['proposed_xml'])
  assert len(prop)>20
 if y.get('change_type')=='normative_reduction':
  assert y['reform_policy_id']=='editorial_direction_2026_10_19'
  assert y['removed_provisions'] and all(len(t)>=30 for t in y['removed_provisions'])
 for e in z['effects']:
  assert e['kind'] in kinds and e['unit'] in units
  assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
  for k in ['kind','measure_id','description','before','after','unit','affected_population','conditions_and_transition','replacement_or_new_burdens','source_quote','proposed_quote']: assert e[k]
  assert len(e['source_quote'])>=12 and e['source_quote'] in plain(x['source_xml']),(x['number'],'source_quote')
  assert len(e['proposed_quote'])>=12 and e['proposed_quote'] in prop,(x['number'],'proposed_quote')
 key=x['code_id']+'|'+x['source_id']; required=r['requirements'][key]
 assert [c['target_key'] for c in y['reference_checks']]==required,x['number']
 for c in y['reference_checks']:
  assert c['view_sha256']==r['targets'][c['target_key']]['view_sha256']
  assert len(c['assessment'])>=80
print('Validation de structure, identités, balises, citations exactes et 41 renvois : conforme.')
print('Statuts :',dict(Counter(x['status'] for x in a)))
print('Impacts :',dict(Counter(x['substantive_impact']['classification'] for x in a)))
for x,y in zip(s,a):
 if y['proposed_xml']:
  old_refs=set(re.findall(r'\\b[LDR]\\.\\s*\\d+(?:-\\d+)+',html.unescape(x['source_xml'])))
  new_refs=set(re.findall(r'\\b[LDR]\\.\\s*\\d+(?:-\\d+)+',html.unescape(y['proposed_xml'])))
  print(y['number'],'renvois ajoutés',sorted(new_refs-old_refs),'renvois retirés',sorted(old_refs-new_refs))
